def test_hyb_mgga_xc_pw86b95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_pw86b95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.102741658518602e+00, -3.045510562501565e+00, -2.965495047111157e+00, -2.855018341353418e+00, -2.705206753792235e+00, -2.507197102676934e+00, -2.254642732293700e+00, -1.947214415790263e+00, -1.592782176939878e+00, -1.206331750278416e+00, -8.160606934179119e-01, -5.580460044398285e-01, -4.627310328365975e-01, -3.821296660949383e-01, -2.834213636369514e-01, -1.813785683310389e-01, -9.909810069240045e-02, -4.573100277451647e-02, -1.732115735323408e-02, -4.620790011129267e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


